import java.io.*;

public class Main {
    static long min(long a, long b) {
        return a < b ? a : b;
    }

    static long max(long a, long b) {
        return a > b ? a : b;
    }

    static long lucky(int i) {
        return i == 1 ? 0 : lucky(i / 2) * 10 + (i % 2 == 0 ? 4 : 7);
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner(System.in);
        long[] aa = new long[2047];
        int l = fs.nextInt();
        int r = fs.nextInt();

        aa[0] = 4;
        for (int i = 1; i < 2047; i++) {
            aa[i] = lucky(i + 1);
        }

        long ans = 0;
        for (int i = 0; i < 2047; i++) {
            long x = max(i == 0 ? 1 : aa[i - 1] + 1, l);
            long y = min(aa[i], r);
            if (x <= y) {
                ans += (y - x + 1) * aa[i];
            }
        }

        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int pointer;
        private int length;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (pointer >= length) {
                length = in.read(buffer);
                pointer = 0;
                if (length <= 0) {
                    return -1;
                }
            }
            return buffer[pointer++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ');

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value * sign;
        }
    }
}

